INSERT INTO faqs (question,answer,sort_no) VALUES
('จองแล้วยกเลิกได้หรือไม่?','ยกเลิกได้ที่เมนู การจองของฉัน > รายละเอียด > ยกเลิกการจอง เงินคืนเข้า Wallet ตามเงื่อนไขของรายการ',0),
('ชำระเงินด้วยวิธีใดได้บ้าง?','รองรับ PromptPay บัตรเครดิต/เดบิต และ Wallet',1),
('Wallet เติมเงินอย่างไร?','ไปที่ Wallet > เติมเงิน แล้วสแกน QR PromptPay',2),
('ติดต่อฝ่ายช่วยเหลือได้อย่างไร?','เปิดหน้า ติดต่อเรา แล้วส่งข้อความ ทีมงานตอบกลับภายใน 24 ชั่วโมง',3);
